-- KTC TEST 046: authoritative GC worker master from Mã hóa (2).xlsx.
-- Deletes only the current GC worker roster. Lead/Manager/Admin and workers assigned to other processes stay intact.
-- Code rule: given name, lowercase ASCII, no spaces; duplicate given names get -2/-3; 49xxx -> 49-xxx.
SET @gc_process_id := (SELECT id FROM processes WHERE UPPER(TRIM(process_code))='GC' LIMIT 1);
DROP TEMPORARY TABLE IF EXISTS tmp_old_gc_workers_20260924;
CREATE TEMPORARY TABLE tmp_old_gc_workers_20260924(worker_id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL);
INSERT INTO tmp_old_gc_workers_20260924 SELECT DISTINCT w.id,w.user_id FROM workers w JOIN users u ON u.id=w.user_id JOIN worker_processes wp ON wp.worker_id=w.id WHERE wp.process_id=@gc_process_id AND u.role='worker';
DELETE FROM worker_processes WHERE process_id=@gc_process_id;
DELETE w FROM workers w JOIN tmp_old_gc_workers_20260924 x ON x.worker_id=w.id LEFT JOIN worker_processes wp ON wp.worker_id=w.id WHERE wp.worker_id IS NULL;
DELETE u FROM users u JOIN tmp_old_gc_workers_20260924 x ON x.user_id=u.id LEFT JOIN workers w ON w.user_id=u.id WHERE w.id IS NULL AND u.role='worker';
DROP TEMPORARY TABLE IF EXISTS tmp_gc046;
CREATE TEMPORARY TABLE tmp_gc046(worker_code VARCHAR(160) PRIMARY KEY,worker_name VARCHAR(255) NOT NULL);
