INSERT INTO users(username,password,full_name,role,status) SELECT t.worker_code,'',t.worker_name,'worker','active' FROM tmp_gc046 t LEFT JOIN users u ON LOWER(TRIM(u.username))=LOWER(TRIM(t.worker_code)) WHERE u.id IS NULL;
INSERT INTO workers(user_id,worker_code,phone,department,position,training_percent,status) SELECT u.id,t.worker_code,NULL,'Sản xuất','Công nhân',100,'active' FROM tmp_gc046 t JOIN users u ON LOWER(TRIM(u.username))=LOWER(TRIM(t.worker_code)) LEFT JOIN workers w ON w.user_id=u.id WHERE w.id IS NULL;
UPDATE users u JOIN tmp_gc046 t ON LOWER(TRIM(u.username))=LOWER(TRIM(t.worker_code)) SET u.full_name=t.worker_name,u.role='worker',u.status='active';
INSERT IGNORE INTO worker_processes(worker_id,process_id) SELECT w.id,@gc_process_id FROM workers w JOIN tmp_gc046 t ON t.worker_code=w.worker_code WHERE @gc_process_id IS NOT NULL;
DROP TEMPORARY TABLE tmp_gc046;
DROP TEMPORARY TABLE tmp_old_gc_workers_20260924;
